* Control Script
.control
* 1. Operating Point
op
let p_diss = -i(VDD) * 1.8
print p_diss

* 2. AC Analysis (Closed-loop transimpedance)
ac dec 20 100 100MEG
let zt_db = vdb(out)
let zin = vdb(in)
meas ac zt_100k find zt_db at=100k
meas ac zin_100k find zin at=100k

* 3. Transient Analysis (Baker 30us integration)
tran 50n 30u
meas tran v_out_10u find v(out) at=10u
meas tran v_out_20u find v(out) at=20u
meas tran v_out_30u find v(out) at=30u
let ramp_rate = (v_out_30u - v_out_10u) / 20u
print ramp_rate

quit
.endc
.end

